(() => {
  const SCRIPT = document.currentScript;
  const PUBLIC_KEY = SCRIPT?.dataset?.key || '';
  const API_BASE = 'https://banner-management-service.keetlo.com';

  const containers = document.querySelectorAll('#keetlo-banner, .keetlo-banner');
  let count = 1;

  containers.forEach((root) => {
    const campaignId = root.getAttribute('data-campaign');
    const width  = root.getAttribute('data-width');
    const height = root.getAttribute('data-height');
    if (!campaignId) { 
      root.textContent = 'Missing campaign id'; 
      return; 
    }

    // Set container styles
    root.style.position = 'relative';
    root.style.overflow = 'hidden';
    if (width && height) {
      root.style.backgroundColor = "ghostwhite"; 
      root.style.width = '100%';
      root.style.maxWidth = `${width}px`; 
      root.style.height = `${height}px`; 
      root.style.maxHeight = `${height}px`;
    }

    fetch(`${API_BASE}/public/inside/campaigns/${encodeURIComponent(campaignId)}/banners?key=${encodeURIComponent(PUBLIC_KEY)}`, {
      credentials: 'omit'
    })
    .then(r => r.json())
    .then(r => {
      if (r.status === "error") {
        console.log(r);
        root.textContent = r.message;
        console.error(r.message);  
        return;  
      }

      const { banners = [] } = r.data;
        
      if (!banners.length) { 
        root.textContent = 'No banners available.'; 
        return; 
      }

      if(count === 1){
      banners.map((b) => {
        function sendBeacon(url) {
        try {
          if (navigator.sendBeacon) navigator.sendBeacon(url);
          else fetch(url, { method: 'POST', keepalive: true });
        } catch (e) {
          console.log(e);
        }
      }
      sendBeacon(`${API_BASE}/public/track/view?bannerId=${encodeURIComponent(b.bannerId)}&key=${encodeURIComponent(PUBLIC_KEY)}`);
      })
      }
      count ++

      const img = document.createElement('img');
      let idx = 0;
      const show = (i) => {
        const b = banners[i];
        if(b.link){
            const link = document.createElement('a');
            link.target = '_blank';
            link.rel = 'noopener noreferrer';
            link.style.display = 'block';
            link.appendChild(img);
            root.innerHTML = '';
            root.appendChild(link);
            link.href = `${API_BASE}/public/track/click?bannerId=${encodeURIComponent(b.bannerId)}&key=${encodeURIComponent(PUBLIC_KEY)}`;
        } else {
            root.appendChild(img)
        }
        img.alt = b.bannerName;
        img.decoding = 'async';
        img.loading = 'lazy';
        img.src = b.imageUrl.startsWith('http') ? b.imageUrl : (API_BASE + b.imageUrl);
        img.style.maxWidth = '100%';
        img.style.width = b.imageWidth+'px';
        img.style.height = b.imageHeight+'px';
      };

      show(idx);

      if (banners.length > 1) {
        const ROTATE_MS = 8000;
        const timer = setInterval(() => { idx = (idx + 1) % banners.length; show(idx); }, ROTATE_MS);

        const obs = new MutationObserver(() => {
          if (!document.body.contains(root)) { clearInterval(timer); obs.disconnect(); }
        });
        obs.observe(document.body, { childList: true, subtree: true });

        const io = new IntersectionObserver((entries) => {
          entries.forEach((e) => {
            if (e.isIntersecting) {
              show(idx);
            }
          });
        }, { threshold: 0.5 });
        io.observe(root);
      }
    })
    .catch((e) => { 
      console.log(e); 
      root.textContent = 'Failed to load banner.'; 
    });
  });
})();
